import{_ as t,o as a,c as n,aj as l}from"./chunks/framework.C6uXqnaX.js";const h=JSON.parse('{"title":"Template syntax","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/templates.md","filePath":"en/guide/templates.md"}'),i={name:"en/guide/templates.md"};function r(s,e,o,d,p,c){return a(),n("div",null,e[0]||(e[0]=[l('<h1 id="template-syntax" tabindex="-1">Template syntax <a class="header-anchor" href="#template-syntax" aria-label="Permalink to &quot;Template syntax&quot;">​</a></h1><p>In Angular, a template is a chunk of HTML. Use special syntax within a template to leverage many of Angular&#39;s features.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Check out Angular&#39;s <a href="/en/essentials/templates">Essentials</a> before diving into this comprehensive guide.</p></div><p>Every Angular component has a <strong>template</strong> that defines the <a href="https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model" target="_blank" rel="noreferrer">DOM</a> that the component renders onto the page. By using templates, Angular is able to automatically keep your page up-to-date as data changes.</p><p>Templates are usually found within either the <code>template</code> property of a <code>*.ts</code> file or the <code>*.html</code> file. To learn more, check out the <a href="/en/guide/components">in-depth components guide</a>.</p><h2 id="how-do-templates-work" tabindex="-1">How do templates work? <a class="header-anchor" href="#how-do-templates-work" aria-label="Permalink to &quot;How do templates work?&quot;">​</a></h2><p>Templates are based on <a href="https://developer.mozilla.org/en-US/docs/Web/HTML" target="_blank" rel="noreferrer">HTML</a> syntax, with additional features such as built-in template functions, data binding, event listening, variables, and more.</p><p>Angular compiles templates into JavaScript in order to build up an internal understanding of your application. One of the benefits of this are built-in rendering optimizations that Angular applies to your application automatically.</p><h3 id="differences-from-standard-html" tabindex="-1">Differences from standard HTML <a class="header-anchor" href="#differences-from-standard-html" aria-label="Permalink to &quot;Differences from standard HTML&quot;">​</a></h3><p>Some differences between templates and standard HTML syntax include:</p><ul><li>Comments in the template source code are not included in the rendered output</li><li>Component and directive elements can be self-closed (e.g., <code>&lt;UserProfile /&gt;</code>)</li><li>Attributes with certain characters (i.e., <code>[]</code>, <code>()</code>, etc.) have special meaning to Angular. See <a href="/en/guide/templates/binding">binding docs</a> and <a href="/en/guide/templates/event-listeners">adding event listeners docs</a> for more information.</li><li>The <code>@</code> character has a special meaning to Angular for adding dynamic behavior, such as <a href="/en/guide/templates/control-flow">control flow</a>, to templates. You can include a literal <code>@</code> character by escaping it as an HTML entity code (<code>&amp;commat;</code> or <code>&amp;#64;</code>).</li><li>Angular ignores and collapses unnecessary whitespace characters. See <a href="/en/guide/templates/whitespace">whitespace in templates</a> for more details.</li><li>Angular may add comment nodes to a page as placeholders for dynamic content, but developers can ignore these.</li></ul><p>In addition, while most HTML syntax is valid template syntax, Angular does not support <code>&lt;script&gt;</code> element in templates. For more information, see the <a href="/en/best-practices/security">Security</a> page.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h2><p>You might also be interested in the following:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Topics</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/en/guide/templates/binding">Binding dynamic text, properties, and attributes</a></td><td style="text-align:left;">Bind dynamic data to text, properties and attributes.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/event-listeners">Adding event listeners</a></td><td style="text-align:left;">Respond to events in your templates.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/two-way-binding">Two-way binding</a></td><td style="text-align:left;">Simultaneously binds a value and propagate changes.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/control-flow">Control flow</a></td><td style="text-align:left;">Conditionally show, hide and repeat elements.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/pipes">Pipes</a></td><td style="text-align:left;">Transform data declaratively.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/ng-content">Slotting child content with ng-content</a></td><td style="text-align:left;">Control how components render content.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/ng-template">Create template fragments with ng-template</a></td><td style="text-align:left;">Declare a template fragment.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/ng-container">Grouping elements with ng-container</a></td><td style="text-align:left;">Group multiple elements together or mark a location for rendering.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/variables">Variables in templates</a></td><td style="text-align:left;">Learn about variable declarations.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/defer">Deferred loading with @defer</a></td><td style="text-align:left;">Create deferrable views with <code>@defer</code>.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/expression-syntax">Expression syntax</a></td><td style="text-align:left;">Learn similarities and differences between Angular expressions and standard JavaScript.</td></tr><tr><td style="text-align:left;"><a href="/en/guide/templates/whitespace">Whitespace in templates</a></td><td style="text-align:left;">Learn how Angular handles whitespace.</td></tr></tbody></table>',15)]))}const g=t(i,[["render",r]]);export{h as __pageData,g as default};
